function makeBlockId(){return 'b'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);}
function simpleMarkdown(src){
  let t=escHtml(src||'');
  t=t.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
  t=t.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');
  const lines=t.split(/\r?\n/);let out=[],inList=false;
  for(const line of lines){
    const m=line.match(/^\s*[-*]\s+(.+)/);
    if(m){if(!inList){out.push('<ul>');inList=true;}out.push('<li>'+m[1]+'</li>');continue;}
    if(inList){out.push('</ul>');inList=false;}
    if(/^###\s+/.test(line))out.push('<h3>'+line.replace(/^###\s+/,'')+'</h3>');
    else if(/^##\s+/.test(line))out.push('<h2>'+line.replace(/^##\s+/,'')+'</h2>');
    else if(/^#\s+/.test(line))out.push('<h1>'+line.replace(/^#\s+/,'')+'</h1>');
    else if(line.trim())out.push('<p>'+line+'</p>');else out.push('<br>');
  }
  if(inList)out.push('</ul>');return out.join('');
}
