function customBlockSignature(blocks){try{return JSON.stringify((blocks||[]).map(b=>({id:b.id,type:b.type,name:b.name,rect:b.rect,config:b.config})));}catch{return String(Date.now());}}
function blockScheduleActive(c,now=new Date()){if(c?._visible===false)return false;const mode=c?._visMode||'always';if(mode==='always')return true;const day=now.getDay();let allowed=mode==='weekdays'?(day>=1&&day<=5):mode==='weekends'?(day===0||day===6):String(c?._visDays||'').split(',').map(Number).includes(day);if(!allowed)return false;const parse=t=>{const m=String(t||'').match(/^(\d{1,2}):(\d{2})$/);return m?Math.min(1439,Math.max(0,+m[1]*60 + +m[2])):null;},mins=now.getHours()*60+now.getMinutes(),start=parse(c?._visStart),end=parse(c?._visEnd);if(start==null||end==null||start===end)return true;return start<end?(mins>=start&&mins<end):(mins>=start||mins<end);}
