function applyCustomBlockRect(el,block){if(!el||!block)return;const r=customBlockRectForDisplay(block,block.rect),px=pxRectFromNormalized(r);el.style.left=px.left.toFixed(1)+'px';el.style.top=px.top.toFixed(1)+'px';el.style.width=px.width.toFixed(1)+'px';el.style.height=px.height.toFixed(1)+'px';}
