  if(mode==='daily'){const n=Math.min(Math.max(3,Number(c.days)||7),14,dl.time.length),cells=[];for(let i=0;i<n;i++){const dt=new Date(dl.time[i]+'T12:00:00'),pp=dl.precipitation_probability_max?.[i]||0;cells.push(`<div class="custom-weather-cell"><div class="t">${i===0?'Today':dt.toLocaleDateString(undefined,{weekday:'short'})}</div><div class="i" data-weather-code="${dl.weather_code[i]}">${LibreDisplayRuntime.getModule('weatherEffects').weatherIconMarkup(dl.weather_code[i],wi(dl.weather_code[i]))}</div><div class="v">${C(dl.temperature_2m_max[i])}° <span style="opacity:.55">${C(dl.temperature_2m_min[i])}°</span></div>${c.showPrecip!==false?`<div class="p">💧${pp}%</div>`:''}</div>`);}el.innerHTML=blockCardHtml(block,`<div class="custom-weather-block"><div class="custom-weather-strip" style="grid-template-columns:repeat(${n},minmax(58px,1fr))">${cells.join('')}</div></div>`);return;}
  if(mode==='hourly'){const n=Math.min(24,Math.max(3,Number(c.hours)||12)),nowH=new Date();nowH.setMinutes(0,0,0);const cells=[];for(let i=0;i<hr.time.length&&cells.length<n;i++){const t=new Date(hr.time[i]);if(t<nowH)continue;const pp=hr.precipitation_probability?.[i]||0;cells.push(`<div class="custom-weather-cell"><div class="t">${escHtml(t.toLocaleTimeString(undefined,{hour:'numeric'}))}</div><div class="i" data-weather-code="${hr.weather_code[i]}">${LibreDisplayRuntime.getModule('weatherEffects').weatherIconMarkup(hr.weather_code[i],wi(hr.weather_code[i]))}</div><div class="v">${C(hr.temperature_2m[i])}°</div>${c.showPrecip!==false?`<div class="p">💧${pp}%</div>`:''}</div>`);}el.innerHTML=blockCardHtml(block,`<div class="custom-weather-block"><div class="custom-weather-strip" style="grid-template-columns:repeat(${cells.length},minmax(58px,1fr))">${cells.join('')}</div></div>`);return;}
  el.innerHTML=blockCardHtml(block,'<div class="custom-block-error">Unknown weather view.</div>');
