function aqiCategory(v){v=Number(v);if(!Number.isFinite(v))return ['Unknown','rgba(255,255,255,.55)'];if(v<=50)return ['Good','#70d66b'];if(v<=100)return ['Moderate','#f3d35c'];if(v<=150)return ['Unhealthy for sensitive groups','#f1a24d'];if(v<=200)return ['Unhealthy','#ef6a67'];if(v<=300)return ['Very unhealthy','#b879d4'];return ['Hazardous','#9b5c69'];}
async function getAirQualityData(force=false){
  if(!cfg.lat||!cfg.lon)throw new Error('Location is not configured');
  const key=cfg.lat+','+cfg.lon,now=Date.now();
  if(airQualityCache.key!==key||!airQualityCache.data){const saved=loadLocalAirQuality(key);if(saved)airQualityCache=saved;}
  if(!force&&airQualityCache.key===key&&airQualityCache.data&&now-airQualityCache.at<10*60000)return airQualityCache.data;
  const url=`https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${encodeURIComponent(cfg.lat)}&longitude=${encodeURIComponent(cfg.lon)}&current=us_aqi,pm2_5,pm10,ozone,uv_index&timezone=auto`;
  const refresh=()=>{
    if(airQualityCache.promise)return airQualityCache.promise;
    airQualityCache.promise=(async()=>{const data=JSON.parse(await fetchRemoteText(url,15*60));if(!data?.current)throw new Error('Air-quality response is missing current data');const at=Date.now();airQualityCache={key,at,data,promise:null};saveLocalAirQuality(key,data,at);notifyAirQualityUpdated();return data;})().catch(e=>{airQualityCache.promise=null;throw e;});
    return airQualityCache.promise;
  };
  if(!force&&airQualityCache.key===key&&airQualityCache.data){void refresh().catch(()=>{});return airQualityCache.data;}
  return refresh();
}
