function videoEmbedUrl(raw,c={}){
  const url=safeHttpUrl(raw);if(!url)return '';
  try{
    const u=new URL(url),host=u.hostname.toLowerCase().replace(/^www\./,'');let base='';
    if(host==='youtu.be'){const id=u.pathname.split('/').filter(Boolean)[0]||'';if(id)base='https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id);}
    else if(host==='youtube.com'||host==='m.youtube.com'){let id=u.searchParams.get('v')||'';const parts=u.pathname.split('/').filter(Boolean);if(!id&&['embed','shorts','live'].includes(parts[0]))id=parts[1]||'';if(id)base='https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id);}
    else if(host==='vimeo.com'||host==='player.vimeo.com'){const id=u.pathname.split('/').filter(Boolean).find(x=>/^\d+$/.test(x))||'';if(id)base='https://player.vimeo.com/video/'+id;}
    if(!base)return '';
    const e=new URL(base);e.searchParams.set('autoplay',c.autoplay===false?'0':'1');e.searchParams.set('muted',c.muted===false?'0':'1');e.searchParams.set('controls',c.controls===false?'0':'1');
    if(base.includes('youtube'))e.searchParams.set('rel','0');return e.href;
  }catch{return '';}
}

