  if(field.type==='select')return `<div class="integration-field-wrap full">${bsel(field.label,id,value,(field.options||[]).map(x=>[x.value,x.label]),true)}${help}</div>`;
  if(field.type==='textarea')return `<div class="block-field full integration-field-wrap"><label for="${id}">${escHtml(field.label)}</label><textarea id="${id}"${field.placeholder?` placeholder="${escHtml(field.placeholder)}"`:''}>${escHtml(value)}</textarea>${help}</div>`;
  const type=['password','url','number','color'].includes(field.type)?field.type:'text',attrs=[];
  if(field.required)attrs.push('required');if(field.placeholder)attrs.push(`placeholder="${escHtml(field.placeholder)}"`);
